budget.value:
fun p =>
  have K := max 1 ⌈524288 * p.L * p.Δ / p.ε ^ 2⌉₊;
  have S := max 1 ⌈(512 * p.σ / p.ε) ^ 2⌉₊;
  have J := min K.log2 (Nat.log 4 (S / (1 + Nat.log 4 S)));
  have c := fun i => 2 * p.h i + 2 * p.l + p.b * ↑(129 + 3 * p.d * (14 + 4 * (2 + p.d + K + S).log2));
  have r := fun i => ∑ u, if c u ≤ c i then (c u)⁻¹ else 0;
  have B := fun m => 4 * Finset.univ.inf' ⋯ fun i => max (c i) (↑m / r i);
  B S + ↑K * (Finset.range (J + 1)).sup fun j => B (2 * (J + 1) * 4 ^ j + if j = J then S else 0) / 2 ^ j

